from fastapi.encoders import jsonable_encoder

encoded = jsonable_encoder(
    {'payload': {'keep': 1, 'leak': 2}},
    include={'payload': {'keep'}},
)
assert encoded == {'payload': {'keep': 1}}

from fastapi import FastAPI, Header, Query

app = FastAPI()

@app.get('/items')
def get_items(
    query_token: str = Query(..., alias='token'),
    header_token: str = Header(..., alias='token'),
):
    return {'query': query_token, 'header': header_token}

parameters = app.openapi()['paths']['/items']['get']['parameters']
assert {(p['name'], p['in']) for p in parameters} == {
    ('token', 'query'),
    ('token', 'header'),
}
